/* ============================================================================
   MSG-01 · Lista de Hilos — cabecera, acciones, error, paginación
   Colores solo vía tokens del sistema de diseño (§1); ningún hex literal.
   ========================================================================== */

.screen {
  min-width: 0;
}

.eyebrow {
  font-family: var(--bw-font-title);
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-steel-mist);
  margin-bottom: 4px;
}

.title {
  font-family: var(--bw-font-title);
  font-size: 20px;
  font-weight: 700;
  color: var(--bw-deep-steel);
  margin-bottom: 3px;
}

.sub {
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  margin-bottom: 16px;
  max-width: 560px;
}

.actionsBar {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 14px;
}

.searchForm {
  position: relative;
  flex: 1;
  max-width: 300px;
}

.searchForm i {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--bw-input-placeholder);
  font-size: 15px;
  pointer-events: none;
}

.searchInput {
  width: 100%;
  height: 36px;
  padding: 0 10px 0 32px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 5px;
  font-size: 13px;
  color: var(--bw-deep-steel);
  outline: none;
  /* La paleta no expone blanco puro: surface-mist es el neutro más cercano
     al fondo de input del HTML aprobado. */
  background: var(--bw-surface-mist);
  transition: border-color 0.15s;
}
.searchInput:focus {
  border-color: var(--bw-calibration-blue);
  box-shadow: var(--bw-focus-halo);
}
.searchInput::placeholder {
  color: var(--bw-input-placeholder);
}

.primaryBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  /* No hay token de blanco puro: warm-cream es el sólido más claro del sistema. */
  color: var(--bw-warm-cream);
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
  transition: opacity 0.12s;
}
.primaryBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

.actionHint {
  font-size: 12px;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.threadCount {
  font-size: 12px;
  color: var(--bw-input-placeholder);
  margin-left: auto;
  white-space: nowrap;
}

.error {
  margin-bottom: 14px;
  padding: 12px 16px;
  border-radius: 5px;
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-sensitive-text);
  font-size: 13px;
  line-height: 1.5;
}

.loading {
  padding: 32px;
  text-align: center;
  font-size: 13px;
  color: var(--bw-steel-mist);
}

.pagination {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-top: 14px;
}

.pageBtn {
  min-width: 30px;
  height: 30px;
  padding: 0 8px;
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: 4px;
  background: var(--bw-surface-mist);
  font-size: 12px;
  color: var(--bw-ink-steel);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: inherit;
  transition: all 0.12s;
}
.pageBtn:hover:not(:disabled):not(.pageActive) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}
.pageActive {
  background: var(--bw-deep-steel);
  border-color: var(--bw-deep-steel);
  color: var(--bw-warm-cream);
  cursor: default;
}
.pageBtn:disabled {
  color: var(--bw-input-placeholder);
  cursor: default;
}

