/* ============================================================================
   MSG-01 · Lista de Hilos — filas y estado vacío
   Colores solo vía tokens del sistema de diseño (§1); ningún hex literal.
   ========================================================================== */

.list {
  list-style: none;
  margin: 0;
  padding: 0;
  /* La paleta no expone blanco puro: surface-mist (#F8F9FB) es el neutro de
     superficie clara más cercano al fondo de tarjeta del HTML aprobado. */
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
  overflow: hidden;
}

.row {
  border-bottom: 1px solid var(--bw-divider-mist);
}
.row:last-child {
  border-bottom: none;
}

.rowBtn {
  display: grid;
  grid-template-columns: 1fr auto;
  grid-template-rows: auto auto;
  gap: 4px 10px;
  width: 100%;
  padding: 14px 18px;
  background: none;
  border: none;
  cursor: pointer;
  font-family: inherit;
  text-align: left;
  color: inherit;
}
.rowBtn:hover {
  background: var(--bw-row-hover-tint);
}
.rowBtn:focus-visible {
  outline: 2px solid var(--bw-calibration-blue);
  outline-offset: -2px;
}

.top {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  grid-column: 1;
  grid-row: 1;
}

.org {
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-deep-steel);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.country {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  padding: 1px 6px;
  border-radius: 2px;
  background: var(--bw-cold-white);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-line-steel);
  white-space: nowrap;
  flex-shrink: 0;
}

.tsRow {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  grid-column: 2;
  grid-row: 1;
}

.ts {
  font-family: var(--bw-font-mono);
  font-size: 10px;
  color: var(--bw-input-placeholder);
  white-space: nowrap;
}

.bot {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  grid-column: 1;
  grid-row: 2;
}

.preview {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.badge {
  font-family: var(--bw-font-mono);
  font-size: 9px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  padding: 2px 7px;
  border-radius: 2px;
  white-space: nowrap;
  flex-shrink: 0;
}

.abierto {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-steel-mist);
  border: 1px solid var(--bw-badge-neutral-border);
}

.consulta {
  background: var(--bw-chip-active-bg);
  color: var(--bw-calibration-blue);
  border: 1px solid var(--bw-chip-active-border);
}

.oferta {
  background: var(--bw-badge-warning-bg);
  color: var(--bw-warning);
  border: 1px solid var(--bw-badge-warning-border);
}

.acuerdo {
  background: var(--bw-badge-success-bg);
  color: var(--bw-signal-green);
  border: 1px solid var(--bw-badge-success-border);
}

.cerrado {
  background: var(--bw-badge-neutral-bg);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  text-decoration: line-through;
}

.empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 48px 24px;
  text-align: center;
  background: var(--bw-surface-mist);
  border: 1px solid var(--bw-line-steel);
  border-radius: 8px;
}

.emptyText {
  margin: 0;
  font-size: 14px;
  color: var(--bw-steel-mist);
  line-height: 1.6;
  max-width: 420px;
}

.emptyHint {
  margin: 0;
  font-size: 12px;
  color: var(--bw-steel-mist);
}

.emptyBtn {
  height: 36px;
  padding: 0 18px;
  background: var(--bw-calibration-blue);
  border: none;
  border-radius: 5px;
  /* No hay token de blanco puro: warm-cream es el sólido más claro del sistema. */
  color: var(--bw-warm-cream);
  font-size: 13px;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  white-space: nowrap;
}
.emptyBtn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
}

