import {
  previewLabel,
  relativeTime,
  stateTone,
  type StateTone,
  type ThreadSummary,
} from '../../lib/threads';
import styles from './ThreadList.module.css';

interface ThreadListProps {
  threads: ThreadSummary[];
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /** Avisa con el ID del hilo, no con el objeto. */
  onOpen: (id: string) => void;
}

/**
 * Los CSS Modules pueden resolver a `undefined` en TypeScript, de ahí el tipo
 * `string | undefined`. En el render se filtra el hueco antes de unir clases.
 */
const TONE_CLASS: Record<StateTone, string | undefined> = {
  neutral: styles.abierto,
  info: styles.consulta,
  warn: styles.oferta,
  success: styles.acuerdo,
  closed: styles.cerrado,
};

/**
 * Lista de hilos de MSG-01. Presentacional: pinta las filas en el orden en que
 * las recibe — el orden es del servidor — y al abrir avisa con el ID del hilo.
 * No carga datos ni pagina.
 */
export function ThreadList({ threads, now = new Date(), onOpen }: ThreadListProps) {
  if (threads.length === 0) {
    return (
      <div className={styles.empty}>
        <p className={styles.emptyText}>
          Todavía no tienes ninguna conversación. Usa el Directorio para contactar con otras organizaciones.
        </p>
        {/* DIR-01 no está en el alcance del MVP: el botón existe pero va apagado,
            con el motivo visible — la misma forma que el botón de subida de INV-01. */}
        <button type="button" className={styles.emptyBtn} disabled>
          Ir al Directorio
        </button>
        <p className={styles.emptyHint}>El Directorio queda fuera del MVP.</p>
      </div>
    );
  }

  return (
    <ul className={styles.list}>
      {threads.map((thread) => {
        const toneClass = TONE_CLASS[stateTone(thread.state)];
        return (
          <li key={thread.id} className={styles.row}>
            {/* El botón lleva TODO el contenido de la fila: su nombre accesible es
                el del hilo (contraparte, preview, estado) y el <li> conserva su rol
                listitem (F-131). Un role="button" sobre el <li> habría anulado el
                listitem implícito y duplicado el botón. */}
            <button
              type="button"
              className={styles.rowBtn}
              onClick={() => onOpen(thread.id)}
            >
              <span className={styles.top}>
                <span className={styles.org}>{thread.counterpartyName}</span>
                {thread.counterpartyCountry && (
                  <span className={styles.country}>{thread.counterpartyCountry}</span>
                )}
              </span>
              <span className={styles.tsRow}>
                <time className={styles.ts} dateTime={thread.lastItemAt}>
                  {relativeTime(thread.lastItemAt, now)}
                </time>
              </span>
              <span className={styles.bot}>
                <span className={styles.preview}>{previewLabel(thread.lastItem)}</span>
                <span className={[styles.badge, toneClass].filter(Boolean).join(' ')}>
                  {thread.state}
                </span>
              </span>
            </button>
          </li>
        );
      })}
    </ul>
  );
}
